public class SchemaValidatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.util.List<String> list(String... items) {
        return new java.util.ArrayList<>(java.util.Arrays.asList(items));
    }

    public static void main(String[] args) {
        try {
            check("missing one column ignoring case",
                  "[email]",
                  String.valueOf(SchemaValidator.missingColumns(list("id", "NAME", "email"), list("ID", "name"))));
            check("nothing missing when the table has extra columns",
                  "[]",
                  String.valueOf(SchemaValidator.missingColumns(list("id"), list("id", "extra"))));
            check("missing keeps required order and spelling",
                  "[Zip, City]",
                  String.valueOf(SchemaValidator.missingColumns(list("Zip", "street", "City"), list("STREET"))));
            check("everything missing against an empty table, and an empty required list",
                  "[a, b] []",
                  SchemaValidator.missingColumns(list("a", "b"), list())
                      + " " + SchemaValidator.missingColumns(list(), list("id")));

            check("isValidTableName users", true, SchemaValidator.isValidTableName("users"));
            check("isValidTableName user_2 and _tmp",
                  "true,true",
                  SchemaValidator.isValidTableName("user_2") + "," + SchemaValidator.isValidTableName("_tmp"));
            check("isValidTableName leading digit", false, SchemaValidator.isValidTableName("2fast"));
            check("isValidTableName hyphen, empty and null",
                  "false,false,false",
                  SchemaValidator.isValidTableName("user-2") + ","
                      + SchemaValidator.isValidTableName("") + ","
                      + SchemaValidator.isValidTableName(null));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected a normal return but got " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

