public class SchemaValidator {

    public static java.util.List<String> missingColumns(java.util.List<String> required,
                                                        java.util.List<String> actual) {
        java.util.List<String> missing = new java.util.ArrayList<>();
        for (String column : required) {
            boolean found = false;
            for (String have : actual) {
                if (have.equalsIgnoreCase(column)) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                missing.add(column);
            }
        }
        return missing;
    }

    public static boolean isValidTableName(String name) {
        if (name == null || name.isEmpty()) {
            return false;
        }
        if (Character.isDigit(name.charAt(0))) {
            return false;
        }
        for (int i = 0; i < name.length(); i++) {
            char c = name.charAt(i);
            if (!Character.isLetterOrDigit(c) && c != '_') {
                return false;
            }
        }
        return true;
    }
}
